import br.com.swconsultoria.nfe.config.ConfiguracoesNfe;
import br.com.swconsultoria.nfe.model.Estado;
import br.com.swconsultoria.nfe.model.Ambiente;
import br.com.swconsultoria.nfe.model.Evento;
import org.junit.Before;
import org.junit.Test;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class MontaCCeTests {

    private ConfiguracoesNfe configuracao;
    private List<Evento> listaCCe;

    @Before
    public void setUp() {
        configuracao = new ConfiguracoesNfe();
        configuracao.setEstado(Estado.SP);
        configuracao.setAmbiente(Ambiente.HOMOLOGACAO);
        configuracao.setZoneId("America/Sao_Paulo");

        listaCCe = new ArrayList<>();
    }

    @Test
    public void testMontaCCe_Success() throws NfeException {
        Evento evento = new Evento();
        evento.setChave("12345678901234567890123456789012345678901234");
        evento.setSequencia(1);
        evento.setCpf("12345678901");
        evento.setCnpj("12345678000195");
        evento.setDataEvento(LocalDateTime.now());
        evento.setMotivo("Correção de teste");

        listaCCe.add(evento);

        TEnvEvento result = CartaCorrecaoUtil.montaCCe(listaCCe, configuracao);

        assertNotNull(result);
        assertEquals(1, result.getEvento().size());

        TEvento tEvento = result.getEvento().get(0);
        assertEquals(ConstantesUtil.VERSAO.EVENTO_CCE, tEvento.getVersao());

        TEvento.InfEvento infEvento = tEvento.getInfEvento();
        assertEquals("ID110110123456789012345678901234567890123456789012341", infEvento.getId());
        assertEquals(Estado.SP.getCodigoUF(), infEvento.getCOrgao());
        assertEquals(Ambiente.HOMOLOGACAO.getCodigo(), infEvento.getTpAmb());
        assertEquals("12345678901", infEvento.getCPF());
        assertEquals("12345678000195", infEvento.getCNPJ());
        assertEquals("12345678901234567890123456789012345678901234", infEvento.getChNFe());
        assertEquals("1", infEvento.getNSeqEvento());
        assertEquals(ConstantesUtil.VERSAO.EVENTO_CCE, infEvento.getVerEvento());

        TEvento.InfEvento.DetEvento detEvento = infEvento.getDetEvento();
        assertEquals(ConstantesUtil.VERSAO.EVENTO_CCE, detEvento.getVersao());
        assertEquals("Carta de Correcao", detEvento.getDescEvento());
        assertEquals("Correção de teste", detEvento.getXCorrecao());
    }

    @Test(expected = NfeException.class)
    public void testMontaCCe_ThrowsException_WhenMoreThan20Events() throws NfeException {
        for (int i = 0; i < 21; i++) {
            Evento evento = new Evento();
            evento.setChave("12345678901234567890123456789012345678901234");
            evento.setSequencia(i + 1);
            evento.setCpf("12345678901");
            evento.setCnpj("12345678000195");
            evento.setDataEvento(LocalDateTime.now());
            evento.setMotivo("Correção de teste");

            listaCCe.add(evento);
        }

        CartaCorrecaoUtil.montaCCe(listaCCe, configuracao);
    }
}

